       '{questions}',(SELECT jsonb_agg(jsonb_set(q.value,'{text_ml}',to_jsonb('{"q_BT_HISTORY_01_07":"വിവരം നൽകുന്ന വ്യക്തിയും കുട്ടിയുമായുള്ള ബന്ധവും","q_BT_HISTORY_01_08":"പരാമർശിച്ചത് ആര്","q_BT_HISTORY_01_09":"പ്രാഥമിക വിവരശേഖരണ തീയതി / തെറാപ്പിസ്റ്റ്","q_BT_HISTORY_02_01":"പ്രധാന ആശങ്കകൾ","q_BT_HISTORY_02_02":"ആദ്യമായി ശ്രദ്ധയിൽപ്പെട്ട പ്രായം / കാലയളവ്","q_BT_HISTORY_02_03":"ഇപ്പോഴത്തെ പെരുമാറ്റ സംബന്ധമായ ആശങ്കകൾ","q_BT_HISTORY_02_04":"രക്ഷിതാവിന്റെയും കുട്ടിയുടെയും പ്രതീക്ഷകൾ","q_BT_HISTORY_03_01":"ആരംഭവും തുടർന്നുള്ള മാറ്റങ്ങളും","q_BT_HISTORY_03_02":"സാധാരണയായി പെരുമാറ്റം ആരംഭിക്കാൻ കാരണമാകുന്ന സാഹചര്യങ്ങൾ","q_BT_HISTORY_03_03":"വീട്ടിലെ പെരുമാറ്റം","q_BT_HISTORY_03_04":"സ്കൂളിലെയും സാമൂഹിക സാഹചര്യങ്ങളിലെയും പെരുമാറ്റം","q_BT_HISTORY_03_05":"സഹായകരമായ ഘടകങ്ങൾ","q_BT_HISTORY_03_06":"മുമ്പ് പരീക്ഷിച്ച മാർഗങ്ങളും ഫലങ്ങളും","q_BT_HISTORY_04_01":"ഗർഭകാലം: അമ്മയുടെ ആരോഗ്യം","q_BT_HISTORY_04_02":"ഗർഭകാല മരുന്നുകൾ / സങ്കീർണതകൾ","q_BT_HISTORY_04_03":"പൂർണ്ണഗർഭകാല ജനനം / മാസം തികയാതെയുള്ള ജനനം","q_BT_HISTORY_04_04":"പ്രസവ രീതി / ജനനസമയത്തെ ഭാരം","q_BT_HISTORY_04_05":"ജനനസമയത്തെ കരച്ചിൽ / സങ്കീർണതകൾ","q_BT_HISTORY_04_06":"നവജാത ശിശു തീവ്രപരിചരണ വിഭാഗത്തിൽ പ്രവേശനം / മഞ്ഞപ്പിത്തം","q_BT_HISTORY_04_07":"ജനനശേഷമുള്ള ഭക്ഷണപ്രശ്നങ്ങളോ മറ്റ് ബുദ്ധിമുട്ടുകളോ","q_BT_HISTORY_05_01":"സാമൂഹിക പുഞ്ചിരി / തല നിയന്ത്രണം","q_BT_HISTORY_05_02":"ഇരിക്കൽ / ഇഴയൽ","q_BT_HISTORY_05_03":"എഴുന്നേറ്റുനിൽക്കൽ / നടത്തം","q_BT_HISTORY_05_04":"കുഞ്ഞുശബ്ദങ്ങൾ / അർത്ഥമുള്ള ആദ്യ വാക്ക്","q_BT_HISTORY_05_05":"രണ്ടുവാക്ക് വാക്യങ്ങൾ","q_BT_HISTORY_05_06":"ടോയ്‌ലറ്റ് പരിശീലനം / സ്വതന്ത്രമായി ഭക്ഷണം കഴിക്കൽ","q_BT_HISTORY_05_07":"മുമ്പ് നേടിയ കഴിവുകൾ നഷ്ടപ്പെടൽ","q_BT_HISTORY_06_01":"രോഗനിർണയം / നിർണയസമയത്തെ പ്രായം / നിർണയിച്ച വ്യക്തി","q_BT_HISTORY_06_02":"അപസ്മാരം / ആശുപത്രിവാസം / ശസ്ത്രക്രിയ","q_BT_HISTORY_06_03":"അലർജികൾ / ഇപ്പോൾ കഴിക്കുന്ന മരുന്നുകൾ","q_BT_HISTORY_06_04":"കേൾവി / കാഴ്ച ബുദ്ധിമുട്ടുകൾ","q_BT_HISTORY_06_05":"ഉറക്കരീതി / ഭക്ഷണം കഴിക്കുന്നതിലെ ബുദ്ധിമുട്ടുകൾ","q_BT_HISTORY_06_06":"മറ്റ്