                      FROM jsonb_array_elements(c.value->'questions') WITH ORDINALITY q(value,ordinality)))
     ORDER BY c.ordinality)
   FROM jsonb_array_elements(s.value->'categories') WITH ORDINALITY c(value,ordinality)
 )) ORDER BY s.ordinality)
 FROM jsonb_array_elements(t.structure) WITH ORDINALITY s(value,ordinality))
WHERE t.title='Behavioural Therapy — Student History Assessment'
AND NOT EXISTS(SELECT 1 FROM public.custom_assessment_assignments a WHERE a.template_id=t.id);